import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"How does the adapter calculate?","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/05.hintergrund/01.berechnung.md"},"headers":[],"relativePath":"adapter/sourceanalytix/hintergrund/berechnung.md","filePath":"adapter/sourceanalytix/hintergrund/berechnung.md","lastUpdated":null}'),n={name:"adapter/sourceanalytix/hintergrund/berechnung.md"};function s(i,e,h,l,d,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="how-does-the-adapter-calculate" tabindex="-1">How does the adapter calculate? <a class="header-anchor" href="#how-does-the-adapter-calculate" aria-label="Permalink to &quot;How does the adapter calculate?&quot;">​</a></h1><p><a id="sourceanalytix-still-maintained"></a></p><h2 id="is-sourceanalytix-still-being-developed" tabindex="-1">Is SourceAnalytix still being developed? <a class="header-anchor" href="#is-sourceanalytix-still-being-developed" aria-label="Permalink to &quot;Is SourceAnalytix still being developed?&quot;">​</a></h2><p><strong>In short:</strong> Yes. After a long break between v0.4.14 (February 2022) and v0.5.0 (July 2026), new versions are being released regularly again, most recently v0.6.0 on 26 September 2026 and v0.6.1 on 7 November 2026. v0.6.2 brings bug fixes, and v0.7.0 brings the new settings page with actions for fixing problems.</p><p>SourceAnalytix is currently in the &quot;latest&quot; (beta) repository. It only moves to &quot;stable&quot; after a test phase. To get a new version, see <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">How do I update SourceAnalytix (and what is a downgrade)?</a>.</p><h3 id="where-to-take-questions-and-bugs" tabindex="-1">Where to take questions and bugs <a class="header-anchor" href="#where-to-take-questions-and-bugs" aria-label="Permalink to &quot;Where to take questions and bugs&quot;">​</a></h3><ol><li>From v0.7.0, first look at the &quot;Problems&quot; tab in the instance settings. It checks all sources and suggests a fix.</li><li>Read the <a href="./../fehlerbehebung/">troubleshooting</a> pages.</li><li>Report a bug or a feature request as an issue in the <a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues" target="_blank" rel="noreferrer">GitHub repository</a>. Check first whether there is already an issue for it. Include the versions of SourceAnalytix, js-controller and Node.js, and attach the log of the affected source.</li></ol><p>Features that many people ask for, such as &quot;Switch datapoint&quot; (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1271" target="_blank" rel="noreferrer">#1271</a>) or a &quot;Sum of all sources&quot;, are marked as planned. On the settings page they carry the label &quot;planned&quot;.</p><p><a id="values-differ-meter-portal-evcc"></a></p><h2 id="why-do-the-values-differ-from-my-meter-portal-or-evcc" tabindex="-1">Why do the values differ from my meter, portal or evcc? <a class="header-anchor" href="#why-do-the-values-differ-from-my-meter-portal-or-evcc" aria-label="Permalink to &quot;Why do the values differ from my meter, portal or evcc?&quot;">​</a></h2><p><strong>In short:</strong> There are usually four possible reasons: the source is a power value in W that sends only rarely; a portal or wallbox assigns the consumption to a different point in time; the device measures differently from your meter; or the start values, unit or total don&#39;t fit. The table helps you find the cause.</p><table tabindex="0"><thead><tr><th>Cause</th><th>How to recognize it</th><th>What helps</th></tr></thead><tbody><tr><td>The source is a power value (W) that sends only every few minutes</td><td>The values differ a lot, often by a multiple</td><td>Use the device&#39;s total counter in kWh, or make the device send more often, for example every 10 seconds</td></tr><tr><td>A power source had a pause</td><td>After an outage, consumption is missing or far too high</td><td>See <a href="#sourceanalytix-convert-watts-kwh">Pauses</a>, from v0.7.0 &quot;Maximum gap between power values (minutes)&quot;</td></tr><tr><td>Different point in time for assigning the consumption</td><td>Daily values differ, but the sum over several days matches</td><td>Nothing, both values are right. Compare longer periods</td></tr><tr><td>The device measures differently from the grid operator&#39;s meter</td><td>Consumption and feed-in don&#39;t match the meter in the basement</td><td>Read the meter itself, for example with a reading head</td></tr><tr><td>Start values, unit or total are wrong</td><td>Values are negative, far too high or off by a fixed amount</td><td>See <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correct wrong values</a></td></tr></tbody></table><h3 id="power-instead-of-a-meter-reading" tabindex="-1">Power instead of a meter reading <a class="header-anchor" href="#power-instead-of-a-meter-reading" aria-label="Permalink to &quot;Power instead of a meter reading&quot;">​</a></h3><p>From a power value, SourceAnalytix can only estimate the consumption. Each value applies until the next one. If a device sends only every 5 minutes, SourceAnalytix counts every short peak for the whole 5 minutes. If the device offers a meter reading in kWh, that is more accurate. For how the conversion works, see <a href="#sourceanalytix-convert-watts-kwh">How does SourceAnalytix convert watts to kWh?</a>.</p><h3 id="different-point-in-time-for-assigning-the-consumption" tabindex="-1">Different point in time for assigning the consumption <a class="header-anchor" href="#different-point-in-time-for-assigning-the-consumption" aria-label="Permalink to &quot;Different point in time for assigning the consumption&quot;">​</a></h3><p>SourceAnalytix books consumption on the day it was measured: The daily value is the total now minus the total at 0:00. A wallbox or evcc, on the other hand, often books a whole charging session on the day it ends. Manufacturer portals sometimes work with 15-minute values. Over days or months, this evens out.</p><h3 id="the-device-measures-differently" tabindex="-1">The device measures differently <a class="header-anchor" href="#the-device-measures-differently" aria-label="Permalink to &quot;The device measures differently&quot;">​</a></h3><p>A Shelly 3EM counts consumption and feed-in per phase. The grid operator&#39;s meter offsets the phases against each other. With feed-in on one phase and consumption on another, the two therefore differ, even though SourceAnalytix calculates correctly.</p><p><strong>See also:</strong> <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Which datapoint do I activate: meter (kWh) or power (W)?</a> · <a href="./../erste-schritte/erster-zaehler#start-values-unit">What do I enter for the start values (and in which unit)?</a></p><p><a id="sourceanalytix-convert-watts-kwh"></a></p><h2 id="how-does-sourceanalytix-convert-watts-to-kwh" tabindex="-1">How does SourceAnalytix convert watts to kWh? <a class="header-anchor" href="#how-does-sourceanalytix-convert-watts-to-kwh" aria-label="Permalink to &quot;How does SourceAnalytix convert watts to kWh?&quot;">​</a></h2><p><strong>In short:</strong> With every new power value, SourceAnalytix calculates the energy since the previous value: previous power × time since the previous value. This is a left Riemann sum. With &quot;Average power values&quot; it uses the average of the previous and the new value instead. The energy is converted to the target unit and added to the total.</p><h3 id="the-formula" tabindex="-1">The formula <a class="header-anchor" href="#the-formula" aria-label="Permalink to &quot;The formula&quot;">​</a></h3><p>Energy in Wh = power in W × time in hours. An example with three values:</p><table tabindex="0"><thead><tr><th>Time</th><th>Value</th><th>without averaging</th><th>with averaging</th></tr></thead><tbody><tr><td>10:00</td><td>0 W</td><td>Starting point</td><td>Starting point</td></tr><tr><td>10:30</td><td>1,000 W</td><td>0 W × 0.5 h = 0 Wh</td><td>500 W × 0.5 h = 250 Wh</td></tr><tr><td>11:00</td><td>1,000 W</td><td>1,000 W × 0.5 h = 500 Wh</td><td>1,000 W × 0.5 h = 500 Wh</td></tr><tr><td>Sum</td><td></td><td>500 Wh = 0.5 kWh</td><td>750 Wh = 0.75 kWh</td></tr></tbody></table><p>Without averaging, the calculation suits devices that switch abruptly and send only when something changes. With averaging, it suits sensors whose power rises and falls smoothly and that send regularly.</p><h3 id="it-only-calculates-when-a-new-value-arrives" tabindex="-1">It only calculates when a new value arrives <a class="header-anchor" href="#it-only-calculates-when-a-new-value-arrives" aria-label="Permalink to &quot;It only calculates when a new value arrives&quot;">​</a></h3><p>SourceAnalytix calculates as soon as the source writes a value, even if the value stays the same. What counts is the value&#39;s timestamp. A device that sends only when something changes is still calculated correctly: The last value applies until a new one arrives.</p><h3 id="pauses" tabindex="-1">Pauses <a class="header-anchor" href="#pauses" aria-label="Permalink to &quot;Pauses&quot;">​</a></h3><ul><li><strong>First value:</strong> After activation, after a restart of SourceAnalytix and after a change of the settings, the first value is only the starting point. The energy of the pause before it is missing.</li><li><strong>Long silence while the instance is running:</strong> If no new value arrives for a long time, SourceAnalytix extends the last value over the whole pause. <strong>From v0.7.0</strong>, &quot;Maximum gap between power values (minutes)&quot; limits this. Longer pauses then count as 0 (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1266" target="_blank" rel="noreferrer">#1266</a>).</li><li><strong>Midnight:</strong> <strong>From v0.6.2</strong>, SourceAnalytix books the energy up to 0:00 to the old day and carries on with the same value in the new day. A value that is older than the previous day is not extrapolated (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1254" target="_blank" rel="noreferrer">#1254</a>).</li><li><strong>Negative values:</strong> With &quot;Ignore negative values&quot; they count as 0 W.</li></ul><p>Power sources have no reset detection and no start values to enter. Their total starts at 0 on activation.</p><p><strong>See also:</strong> <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Which datapoint do I activate: meter (kWh) or power (W)?</a> · <a href="./../anleitungen/quellen-und-einheiten#sourceanalytix-compute-consumption-meter-reading">Can SourceAnalytix calculate consumption and a meter reading from power (W)?</a></p><p><a id="consumption-calculated-currentyear-lower-than"></a></p><h2 id="how-is-consumption-calculated-and-why-is-currentyear-lower-than-my-meter-reading" tabindex="-1">How is consumption calculated, and why is currentYear lower than my meter reading? <a class="header-anchor" href="#how-is-consumption-calculated-and-why-is-currentyear-lower-than-my-meter-reading" aria-label="Permalink to &quot;How is consumption calculated, and why is currentYear lower than my meter reading?&quot;">​</a></h2><p><strong>In short:</strong> This is by design. <code>currentYear.consumed.05_currentYear</code> is this year&#39;s consumption, not the meter reading: total minus the &quot;Year&quot; start value. You find the meter reading itself in <code>sourceanalytix.0.&lt;device&gt;.cumulativeReading</code>.</p><p>The same formula applies to every period: consumption = total − start value of the period. The start value is the total at the beginning of the period. SourceAnalytix sets it itself at every period rollover, for example on 1 January at 0:00 for &quot;Year&quot;.</p><table tabindex="0"><thead><tr><th></th><th>Value</th></tr></thead><tbody><tr><td>Total (<code>cumulativeReading</code>)</td><td>12,480 kWh</td></tr><tr><td>&quot;Year&quot; start value (total on 1 January)</td><td>11,900 kWh</td></tr><tr><td><code>05_currentYear</code></td><td>580 kWh</td></tr></tbody></table><p>If you only activated SourceAnalytix during the year, the &quot;Year&quot; start value is the total at the time of activation. The year then counts from that day. If you want it to count from 1 January, enter the meter reading from 1 January as the start value, see <a href="./../erste-schritte/erster-zaehler#start-values-unit">What do I enter for the start values (and in which unit)?</a>.</p><p>SourceAnalytix stores the meter reading at the end of each period under <code>currentYear.meterReadings</code> if &quot;Store meter readings&quot; is on.</p><p><strong>See also:</strong> <a href="./../referenz/states-und-meldungen#meter-readings-cumulative">Meter readings per period (meterReadings)</a> · <a href="./../erste-schritte/erster-zaehler#values-consumption-today-yesterday">Where do I find my values (daily consumption today/yesterday)?</a></p>',40)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
